  "recovered_c": "#include <stdint.h>\n#include <stddef.h>\n\nuint64_t fn_14(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  size_t o = 0;\n  size_t i = 0;\n\n  if (out_cap < (len + 2) / 3 << 2) {\n    return 0xFFFFFFFFFFFFFFFF;\n  }\n\n  for (; i + 3 <= len; i += 3) {\n    uint32_t uVar4 = (uint32_t)in[i] << 16 | (uint32_t)in[i + 1] << 8;\n    uint8_t bVar2 = in[i + 2];\n    \n    out[o] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\")[in[i] >> 2];\n    out[o + 1] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\")[ (uVar4 & 0x3f000) >> 12 ];\n    out[o + 2] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\")[ (bVar2 | uVar4) >> 6 & 0x3f ];\n    out[o + 3] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\")[ bVar2 & 0x3f ];\n    \n    o += 4;\n  }\n\n  if (len - i == 1) {\n    uint8_t bVar2 = in[i];\n    out[o] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\")[bVar2 >> 2];\n    out[o + 1] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\")[ (bVar2 & 3) << 4 ];\n    out[o + 2] = '=';\n    out[o + 3] = '=';\n    o += 4;\n  }\n  else if (len - i == 2) {\n    uint8_t bVar2 = in[i];\n    uint8_t bVar3 = in[i + 1];\n    out[o] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\")[bVar2 >> 2];\n    out[o + 1] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\")[ ( ( (uint32_t)bVar3 << 8 | (uint32_t)bVar2 << 16 ) >> 12 ) & 0x3f ];\n    out[o + 2] = \"AfhmdLEr3GMxg2S/a91UZnTlHOI5KYzevFCwNQ+P4tWV7cpXRbDuykjJsoi6q80B\")[ ( ( (uint32_t)bVar3 << 8 ) & 0xfc0 ) >> 6 ];\n    out[o + 3] = '=';\n    o += 4;\n  }\n\n  return o;\n}\n"
